PRAGMA foreign_keys = OFF;

DELETE FROM blog_comments;

DELETE FROM blog_relationships;

DELETE FROM blog_contents;

DELETE FROM blog_metas;

DELETE FROM blog_links;

DELETE FROM blog_options;

DELETE FROM blog_cookies;

